// QA-only independent FIFO/deadline/health probe. Real frozen native S7 Server, transparent finite proxy.
use field_flow::{config::Config, domain::id, infrastructure::state::{self,State},runtime::Runtime};
use serde_json::json;
use std::{io::{Read,Write,BufRead,BufReader},net::{TcpListener,TcpStream,Shutdown},path::Path,sync::{Arc,Mutex,atomic::{AtomicBool,AtomicU64,Ordering}},thread,time::Duration,process::{Command,Stdio}};
fn frame(s:&mut TcpStream)->std::io::Result<Vec<u8>>{let mut h=[0;4];s.read_exact(&mut h)?;let n=u16::from_be_bytes([h[2],h[3]])as usize;if h[..2]!=[3,0]||!(4..=4096).contains(&n){return Err(std::io::ErrorKind::InvalidData.into())}let mut v=vec![0;n];v[..4].copy_from_slice(&h);s.read_exact(&mut v[4..])?;Ok(v)}
fn main(){let q=std::env::args().nth(1).unwrap();let root=Path::new(&q);let until=std::time::Instant::now();
let listener=TcpListener::bind("127.0.0.1:31102").unwrap(); listener.set_nonblocking(true).unwrap();
drop(TcpListener::bind("127.0.0.1:31103").unwrap());
let mut native=Command::new(root.join("rust-formal-target/debug/ff-fixture")).arg("__native_fixture").stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::null()).spawn().unwrap();
let native_pid=native.id();let mut line=String::new();BufReader::new(native.stdout.take().unwrap()).read_line(&mut line).unwrap();assert_eq!(line.trim(),"ready");
let stop=Arc::new(AtomicBool::new(false));let received=Arc::new(AtomicU64::new(0));let connections=Arc::new(Mutex::new(Vec::<TcpStream>::new()));let trace=Arc::new(Mutex::new(Vec::new()));
let (s,r,peers,tr)=(stop.clone(),received.clone(),connections.clone(),trace.clone());
let proxy=thread::spawn(move||{let mut jobs=Vec::new();while !s.load(Ordering::Acquire){match listener.accept(){Ok((mut front,_))=>{front.set_read_timeout(Some(Duration::from_millis(100))).unwrap();let mut back=TcpStream::connect("127.0.0.1:31103").unwrap();back.set_read_timeout(Some(Duration::from_secs(1))).unwrap();peers.lock().unwrap().extend([front.try_clone().unwrap(),back.try_clone().unwrap()]);let(s,r,tr)=(s.clone(),r.clone(),tr.clone());jobs.push(thread::spawn(move||{while !s.load(Ordering::Acquire){let req=match frame(&mut front){Ok(v)=>v,Err(e)if matches!(e.kind(),std::io::ErrorKind::WouldBlock|std::io::ErrorKind::TimedOut)=>continue,Err(_)=>break};let op=if req.get(7..9)==Some(&[0x32,1]){req.get(17).copied().unwrap_or(0)}else{0};if back.write_all(&req).is_err(){break}let ack=match frame(&mut back){Ok(v)=>v,Err(_)=>break};if op==4{r.fetch_add(1,Ordering::SeqCst);thread::sleep(Duration::from_millis(600));}tr.lock().unwrap().push(json!({"operation":op,"request_hex":req.iter().map(|b|format!("{b:02x}")).collect::<String>(),"original_response_hex":ack.iter().map(|b|format!("{b:02x}")).collect::<String>(),"forwarded_response_hex":ack.iter().map(|b|format!("{b:02x}")).collect::<String>()}));if front.write_all(&ack).is_err(){break}}}));},Err(e)if e.kind()==std::io::ErrorKind::WouldBlock=>thread::sleep(Duration::from_millis(2)),Err(e)=>panic!("accept {e}")}}for h in jobs{h.join().unwrap();}});
let rt=tokio::runtime::Builder::new_multi_thread().worker_threads(4).enable_all().build().unwrap();
let summary=rt.block_on(async{
let mut c=Config::load(Path::new("config/loopback.yaml")).unwrap();c.plcs[0].io_timeout_ms=1200;c.plcs[0].queue_wait_ms=2000;c.validate().unwrap();
let dir=root.join("rust-fifo-probe-state");state::init(&dir,"execute",&c.instance_id).unwrap();let(st,task)=State::open(&dir,"execute",&c.instance_id,&id()).unwrap();let runtime=Runtime::start(&c,&dir,&root.join("rust-formal-target/debug/field-flow"),st.clone()).unwrap();
let end=tokio::time::Instant::now()+Duration::from_secs(4);while runtime.owners["plc_demo"].health().state!="ready"{assert!(tokio::time::Instant::now()<end);tokio::time::sleep(Duration::from_millis(2)).await;}
let owner=runtime.owners["plc_demo"].clone();let start=tokio::time::Instant::now();let first=tokio::spawn(async move{owner.read("first",1,0).await});while received.load(Ordering::Acquire)<1{tokio::time::sleep(Duration::from_millis(2)).await;}
let second_start=tokio::time::Instant::now();let second=runtime.owners["plc_demo"].read("second",1,0).await;let second_ms=second_start.elapsed().as_millis();let first=first.await.unwrap();let first_result=first.as_ref().map(|s|s.value).map_err(|e|e.clone());let second_result=second.as_ref().map(|s|s.value).map_err(|e|e.clone());let shutdown=runtime.shutdown(15000).await;drop(st);task.join().await.unwrap();
json!({"case":"queued-IO-budget","io_timeout_ms":1200,"queue_wait_ms":2000,"per_response_delay_ms":600,"first":first_result,"second":second_result,"second_elapsed_ms":second_ms,"total_ms":start.elapsed().as_millis(),"expected":"both fresh S7 reads succeed: queue wait under2000ms, each dispatched IO600ms under800ms work budget","shutdown":shutdown,"actual_readvar":received.load(Ordering::Acquire),"state":state::inspect(&dir).unwrap()})});
stop.store(true,Ordering::Release);for peer in connections.lock().unwrap().iter(){let _=peer.shutdown(Shutdown::Both);}proxy.join().unwrap();native.stdin.as_mut().unwrap().write_all(b"stop\n").unwrap();drop(native.stdin.take());let status=native.wait().unwrap();assert!(status.success());for port in[31102,31103]{drop(TcpListener::bind(("127.0.0.1",port)).unwrap());}
let output=json!({"summary":summary,"protocol":trace.lock().unwrap().clone(),"native_pid":native_pid,"native_exit":status.code(),"proxy_joined":true,"ports_rebound":[31102,31103],"duration_ms":until.elapsed().as_millis()});std::fs::write(root.join("rust-fifo-probe.json"),serde_json::to_vec_pretty(&output).unwrap()).unwrap();println!("{}",output);
if output["summary"]["second"]["Err"].is_string(){std::process::exit(1)}
}
